'use strict';

function createRepairDesk(notify) {
  if (typeof notify !== 'function') {
    throw new TypeError('notify must be a function');
  }

  const tickets = new Map();
  const notices = [];
  let nextId = 1;

  function text(value, name) {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new TypeError(name + ' must be non-empty');
    }
    return value.trim();
  }

  function get(ticketId) {
    if (!Number.isInteger(ticketId) || ticketId <= 0 || !tickets.has(ticketId)) {
      throw new RangeError('unknown ticket');
    }
    return tickets.get(ticketId);
  }

  function copyTicket(ticket) {
    return { ...ticket };
  }

  function commit(ticket) {
    const notice = {
      ticketId: ticket.ticketId,
      owner: ticket.owner,
      status: ticket.status
    };

    tickets.set(ticket.ticketId, ticket);
    notify({ ...notice });
    notices.push({ ...notice });
    return copyTicket(ticket);
  }

  function open(summary, owner) {
    const cleanSummary = text(summary, 'summary');
    const cleanOwner = text(owner, 'owner');
    const ticket = {
      ticketId: nextId,
      summary: cleanSummary,
      owner: cleanOwner,
      technician: null,
      status: 'open'
    };

    const result = commit(ticket);
    nextId += 1;
    return result;
  }

  function assign(ticketId, technician) {
    const cleanTechnician = text(technician, 'technician');
    const current = get(ticketId);
    if (current.status === 'closed') {
      throw new RangeError('ticket is closed');
    }
    return commit({
      ...current,
      technician: cleanTechnician,
      status: 'assigned'
    });
  }

  function close(ticketId) {
    const current = get(ticketId);
    if (current.status === 'closed') {
      throw new RangeError('ticket is closed');
    }
    return commit({ ...current, status: 'closed' });
  }

  function list(status) {
    if (!['all', 'open', 'assigned', 'closed'].includes(status)) {
      throw new TypeError('invalid status');
    }

    return [...tickets.values()]
      .filter(ticket => status === 'all' || ticket.status === status)
      .sort((a, b) => a.ticketId - b.ticketId)
      .map(copyTicket);
  }

  function drainNotices() {
    const result = notices.map(notice => ({ ...notice }));
    notices.length = 0;
    return result;
  }

  return { open, assign, close, list, drainNotices };
}

module.exports = { createRepairDesk };

