'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['createRepairDesk']);
const { createRepairDesk } = api;
assert.throws(() => createRepairDesk(null), TypeError);

const delivered = [];
const desk = createRepairDesk(notice => {
  delivered.push(notice);
  notice.owner = 'mutated by notifier';
});
const first = desk.open('  Broken display  ', '  Alice  ');
assert.deepStrictEqual(first, {
  ticketId: 1, summary: 'Broken display', owner: 'Alice',
  technician: null, status: 'open'
});
const second = desk.open('No sound', 'Bob');
assert.strictEqual(second.ticketId, 2);
assert.deepStrictEqual(desk.assign(1, '  Tech One  '), {
  ticketId: 1, summary: 'Broken display', owner: 'Alice',
  technician: 'Tech One', status: 'assigned'
});
assert.deepStrictEqual(desk.close(1), {
  ticketId: 1, summary: 'Broken display', owner: 'Alice',
  technician: 'Tech One', status: 'closed'
});
assert.strictEqual(delivered.length, 4);
assert.deepStrictEqual(desk.list('open').map(t => t.ticketId), [2]);
assert.deepStrictEqual(desk.list('closed').map(t => t.ticketId), [1]);
assert.deepStrictEqual(desk.list('assigned'), []);
assert.deepStrictEqual(desk.list('all').map(t => t.ticketId), [1, 2]);
assert.throws(() => desk.list('invalid'), TypeError);
assert.throws(() => desk.assign(99, 'Tech'), RangeError);
assert.throws(() => desk.assign(1, 'Tech'), RangeError);
assert.throws(() => desk.close(1), RangeError);
assert.throws(() => desk.open('', 'Owner'), TypeError);
assert.throws(() => desk.open('Summary', ' '), TypeError);
assert.throws(() => desk.assign(2, ''), TypeError);

const tickets = desk.list('all');
tickets[0].owner = 'changed';
tickets.pop();
assert.strictEqual(desk.list('all')[0].owner, 'Alice');
assert.strictEqual(desk.list('all').length, 2);

const notices = desk.drainNotices();
assert.deepStrictEqual(notices, [
  { ticketId: 1, owner: 'Alice', status: 'open' },
  { ticketId: 2, owner: 'Bob', status: 'open' },
  { ticketId: 1, owner: 'Alice', status: 'assigned' },
  { ticketId: 1, owner: 'Alice', status: 'closed' }
]);
notices[0].owner = 'changed';
assert.deepStrictEqual(desk.drainNotices(), []);

const failure = new Error('notification failed');
let fail = true;
const atomic = createRepairDesk(() => { if (fail) throw failure; });
assert.throws(() => atomic.open('Issue', 'Owner'), error => error === failure);
assert.deepStrictEqual(atomic.list('all'), []);
assert.deepStrictEqual(atomic.drainNotices(), []);
fail = false;
assert.strictEqual(atomic.open('Issue', 'Owner').ticketId, 1);
fail = true;
assert.throws(() => atomic.assign(1, 'Tech'), error => error === failure);
assert.strictEqual(atomic.list('all')[0].status, 'open');
assert.strictEqual(atomic.list('all')[0].technician, null);
assert.deepStrictEqual(atomic.drainNotices(), [{ ticketId: 1, owner: 'Owner', status: 'open' }]);

